function normalizeBarcode(value: string) {
  return value.trim().toUpperCase().replace(/[^A-Z0-9]/g, "");
}

export function findWarehouseBarcode(value: string) {
  const normalized = normalizeBarcode(value);
  if (!normalized) return null;

  return (
    WAREHOUSE_BARCODES.find((entry) =>
      [entry.label, entry.productCode, entry.variantCode, entry.barcode].some((candidate) => normalizeBarcode(candidate) === normalized),
    ) ?? null
  );
}

export function normalizeWarehouseToken(value: string) {
  return normalizeBarcode(value);
}
